import React, { useState } from "react";
import Sidebarmov from "../../components/Sidebarmov";
import HeaderPanel from "../../components/HeaderPanel";
import "../../components/admin.css"; 
// Importamos Axios para las peticiones HTTP
import axios from 'axios'; 

// URL base de tu API
const API_URL = "http://localhost:3001/api/productos"; 

export default function FormularioEntradaProducto() {
    // 1. Estados para el formulario y la búsqueda de producto
    const [formData, setFormData] = useState({
        id_producto: '',
        cantidad_m: '',
        observaciones: '',
        id_usuario: 1, // Asume un ID de usuario fijo o obtenlo del contexto de autenticación
    });

    const [productoEncontrado, setProductoEncontrado] = useState(null);
    const [mensaje, setMensaje] = useState({ text: '', type: '' });
    const [cargando, setCargando] = useState(false);

    // Función genérica para manejar cambios en los campos del formulario
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    // Función para buscar el producto cuando se ingresa el ID
    const handleCheckProducto = async (e) => {
        // Ejecuta la búsqueda solo si la tecla presionada es 'Enter'
        if (e.key === 'Enter') {
            e.preventDefault(); // Previene el envío del formulario por defecto

            const id = formData.id_producto;
            if (!id) return;

            setCargando(true);
            setMensaje({ text: '', type: '' });
            setProductoEncontrado(null);

            try {
                const response = await axios.get(`${API_URL}/check/${id}`);

                if (response.data.found) {
                    setProductoEncontrado(response.data.product);
                    setMensaje({ text: `Producto encontrado: ${response.data.product.nom_producto}. Stock actual: ${response.data.product.stock_actual}`, type: 'success' });
                }
            } catch (error) {
                // Captura el error 404 de producto no encontrado
                if (error.response && error.response.status === 404) {
                    setMensaje({ text: 'Producto no encontrado. Verifique el ID.', type: 'error' });
                } else {
                    console.error("Error al verificar producto:", error);
                    setMensaje({ text: 'Error de conexión con el servidor.', type: 'error' });
                }
            } finally {
                setCargando(false);
            }
        }
    };

    // Función para manejar el envío del formulario
    const handleSubmit = async (e) => {
        e.preventDefault();

        // Validaciones básicas
        if (!productoEncontrado) {
            setMensaje({ text: 'Debe buscar y validar el ID de un producto existente.', type: 'error' });
            return;
        }
        if (!formData.cantidad_m || formData.cantidad_m <= 0) {
            setMensaje({ text: 'Ingrese una cantidad válida mayor a cero.', type: 'error' });
            return;
        }

        setCargando(true);
        setMensaje({ text: '', type: '' });

        // Los datos que necesita el backend (POST /productos/inventario)
        const dataToSend = {
            id_usuario: formData.id_usuario,
            cantidad_m: formData.cantidad_m,
            observaciones: formData.observaciones,
            es_nuevo_producto: 'false', // Siempre 'false' para esta ruta de entrada de stock
            id_producto_existente: formData.id_producto,
            // Los campos de nuevo producto (nom_producto, etc.) no son necesarios aquí
        };

        try {
            // El backend maneja la actualización del stock y el registro del movimiento
            const response = await axios.post(`${API_URL}/inventario`, dataToSend, {
                headers: { 'Content-Type': 'application/json' },
            });

            setMensaje({ text: response.data.message || 'Entrada registrada con éxito.', type: 'success' });

            // Opcional: Limpiar el formulario y resetear estados
            setFormData(prev => ({ ...prev, cantidad_m: '', observaciones: '' }));
            setProductoEncontrado(null);

        } catch (error) {
            console.error("Error al registrar entrada:", error.response || error);
            const errorMessage = error.response?.data?.error || "Error al registrar la entrada de inventario.";
            setMensaje({ text: errorMessage, type: 'error' });
        } finally {
            setCargando(false);
        }
    };

    // Función para limpiar todos los campos y estados
    const handleReset = () => {
        setFormData({
            id_producto: '',
            cantidad_m: '',
            observaciones: '',
            id_usuario: 1, // Mantener el ID de usuario
        });
        setProductoEncontrado(null);
        setMensaje({ text: '', type: '' });
    };

    return (
        <div className="dashboard-layout">
            <Sidebarmov />

            <main className="contenido">
                <HeaderPanel title="📦 Registro de Entrada de Stock"/>

                {/* Mostrar mensajes de éxito o error */}
                {mensaje.text && (
                    <div className={`alerta ${mensaje.type}`}>
                        {mensaje.text}
                    </div>
                )}

                <section className="cuadro-blanco form-producto">

                    <form className="formulario" onSubmit={handleSubmit}>

                        {/* ID Producto (BUSCADOR) */}
                        <div className="campo">
                            <label htmlFor="id_producto">ID del Producto a Ingresar</label>
                            <input 
                                type="number" 
                                id="id_producto" 
                                name="id_producto" 
                                placeholder="Ingrese el ID y presione ENTER" 
                                required 
                                value={formData.id_producto}
                                onChange={handleChange}
                                onKeyPress={handleCheckProducto}
                                disabled={cargando}
                            />
                            {cargando && <p className="cargando">Cargando...</p>}
                        </div>

                        {/* Detalles del Producto (Solo lectura) */}
                        <div className="campo">
                            <label htmlFor="nombre_producto">Nombre del Producto</label>
                            <input 
                                type="text" 
                                id="nombre_producto" 
                                name="nombre_producto" 
                                placeholder="Producto no validado o no encontrado" 
                                required 
                                readOnly // El usuario NO debe editar el nombre
                                // Muestra el nombre del producto encontrado o un campo vacío
                                value={productoEncontrado ? productoEncontrado.nom_producto : ''}
                                className={productoEncontrado ? 'valido' : 'invalido'}
                            />
                        </div>

                        {/* Stock Actual (Solo lectura) */}
                        <div className="campo">
                            <label htmlFor="stock_actual">Stock Actual</label>
                            <input 
                                type="number" 
                                id="stock_actual" 
                                name="stock_actual" 
                                readOnly 
                                value={productoEncontrado ? productoEncontrado.stock_actual : ''}
                                placeholder="N/A"
                                className='info'
                            />
                        </div>

                        {/* Cantidad ingresada */}
                        <div className="campo">
                            <label htmlFor="cantidad_m">Cantidad ingresada</label>
                            <input 
                                type="number" 
                                id="cantidad_m" 
                                name="cantidad_m" 
                                placeholder="Cantidad de unidades que entran" 
                                required 
                                min="1"
                                value={formData.cantidad_m}
                                onChange={handleChange}
                                disabled={!productoEncontrado || cargando} // Deshabilitado si no hay producto validado
                            />
                        </div>

                        {/* El campo Destinatario/Proveedor no se usa en el backend de 'inventario' 
                            (solo se usa el id_usuario y observaciones), por lo que lo removemos o 
                            lo incluimos en Observaciones.
                        */}

                        {/* Observaciones */}
                        <div className="campo">
                            <label htmlFor="observaciones">Observaciones (Proveedor, #Factura, etc.)</label>
                            <textarea 
                                id="observaciones" 
                                name="observaciones" 
                                placeholder="Ej: Recibido de Proveedor X con Factura #1234" 
                                rows="3"
                                value={formData.observaciones}
                                onChange={handleChange}
                                disabled={!productoEncontrado || cargando}
                            ></textarea>
                        </div>

                        {/* Botones de acción */}
                        <div className="botones">
                            <button type="submit" className="btn-guardar" disabled={!productoEncontrado || cargando}>
                                <i className="fa-solid fa-floppy-disk"></i> {cargando ? 'Registrando...' : 'Registrar Entrada'}
                            </button>
                            <button type="button" className="btn-cancelar" onClick={handleReset} disabled={cargando}>
                                <i className="fa-solid fa-xmark"></i> Cancelar
                            </button>
                        </div>
                    </form>
                </section>
            </main>
        </div>
    );
}
